package com.hospital.system.controller; import com.hospital.system.service.ReportService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/reports") public class ReportController {private final ReportService s; public ReportController(ReportService s){this.s=s;} @GetMapping("/revenue") public Object revenue(){return s.revenue();} @GetMapping("/appointments") public Object appointments(){return s.appointments();} @GetMapping("/pending-bills") public Object pending(){return s.pending();} @GetMapping("/paid-bills") public Object paid(){return s.paid();} @GetMapping("/patient-history/{patientId}") public Object history(@PathVariable Long patientId){return s.history(patientId);} }
